def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1

    letters = list(dict.fromkeys(alphabet))
    index_of = {ch: i for i, ch in enumerate(letters)}
    alpha_size = len(letters)

    words = []
    seen = set()
    for word in banned:
        if not word or word in seen or any(ch not in index_of for ch in word):
            continue
        seen.add(word)
        words.append(word)

    if not words:
        return pow(alpha_size, n, MOD)

    trie = [[-1] * alpha_size]
    terminal = [False]
    for word in words:
        node = 0
        for ch in word:
            bit = index_of[ch]
            nxt = trie[node][bit]
            if nxt == -1:
                nxt = len(trie)
                trie[node][bit] = nxt
                trie.append([-1] * alpha_size)
                terminal.append(False)
            node = nxt
        terminal[node] = True

    count = len(trie)
    fail = [0] * count
    trans = [[0] * alpha_size for _ in range(count)]
    queue = deque()
    for bit in range(alpha_size):
        child = trie[0][bit]
        if child == -1:
            trans[0][bit] = 0
        else:
            trans[0][bit] = child
            fail[child] = 0
            queue.append(child)

    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        parent_fail = fail[node]
        for bit in range(alpha_size):
            child = trie[node][bit]
            if child == -1:
                trans[node][bit] = trans[parent_fail][bit]
            else:
                fail[child] = trans[parent_fail][bit]
                trans[node][bit] = child
                queue.append(child)

    for node in order:
        terminal[node] = terminal[node] or terminal[fail[node]]

    good = [node for node in range(count) if not terminal[node]]
    rank = {node: i for i, node in enumerate(good)}
    size = len(good)
    matrix = [[0] * size for _ in range(size)]
    for node in good:
        row = matrix[rank[node]]
        for bit in range(alpha_size):
            dest = trans[node][bit]
            if not terminal[dest]:
                row[rank[dest]] += 1

    def multiply(left, right):
        product = [[0] * size for _ in range(size)]
        for i in range(size):
            left_row = left[i]
            out_row = product[i]
            for k in range(size):
                value = left_row[k]
                if not value:
                    continue
                right_row = right[k]
                for j in range(size):
                    out_row[j] = (out_row[j] + value * right_row[j]) % MOD
        return product

    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    exponent = n
    while exponent:
        if exponent & 1:
            result = multiply(result, matrix)
        matrix = multiply(matrix, matrix)
        exponent >>= 1
    return sum(result[rank[0]]) % MOD
